WITH base AS (SELECT id, full_name, email, dept_id, job_title, salary, hire_date, level, ROUND(salary, 0) AS salary_rounded, COALESCE(job_title, 'Unknown') AS job_title_filled, COALESCE(job_title, 'UNKNOWN') AS job_title_filled_2 FROM employees WHERE manager_id IS NOT NULL) SELECT p.location, src.job_title, COUNT(*) AS rows_total, ROUND(AVG(src.salary_rounded), 2) AS avg_salary_rounded, GROUPING_ID() AS level_id FROM base src LEFT JOIN departments p ON src.dept_id = p.id GROUP BY ROLLUP (p.location, src.job_title)
